const broker = new EventBroker();
const replay = new ReplayBuffer();

const received: string[] = [];
broker.subscribe("user.*", (ev) => {
    received.push(ev.id);
    replay.record(ev);
});

broker.publish({ id: "e1", topic: "user.created", timestamp: Date.now(), payload: { uid: 1 } });
broker.publish({ id: "e2", topic: "user.updated", timestamp: Date.now(), payload: { uid: 1 } });
broker.publish({ id: "e3", topic: "order.created", timestamp: Date.now(), payload: { oid: 99 } });

if (received.length !== 2 || received[0] !== "e1" || received[1] !== "e2") {
    throw new Error("Event routing failed: " + JSON.stringify(received));
}

const history = replay.replay("user.*");
if (history.length !== 2) {
    throw new Error("Replay buffer failed: " + JSON.stringify(history));
}

console.log("TypeScript Multi-Module Event Broker Test Passed!");
